/**
 * Lap legacy CSS-filter scale: 0..=200 with neutral 100.
 * Recipe deviation scale: -100..=100 with neutral 0 (RapidRAW semantics).
 * The conversion is arithmetic; field names are never matched by similarity.
 */
function clamp(value: number, min: number, max: number): number {
  if (Number.isNaN(value)) return min;
  return Math.min(max, Math.max(min, value));
}

export function saturationFromLapLegacy(legacy: number): number {
  return clamp(legacy, 0, 200) - 100;
}

export function saturationToLapLegacy(recipe: number): number {
  return clamp(recipe, -100, 100) + 100;
}
